import json


class IdMap:
    def __init__(self):
        self._a_to_b = {}
        self._b_to_a = {}

    def link(self, a, b):
        if self._a_to_b.get(a) == b:
            return
        if a in self._a_to_b:
            raise ValueError(f"{a!r} is already linked to {self._a_to_b[a]!r}")
        if b in self._b_to_a:
            raise ValueError(f"{b!r} is already linked to {self._b_to_a[b]!r}")
        self._a_to_b[a] = b
        self._b_to_a[b] = a

    def b_for(self, a):
        return self._a_to_b.get(a)

    def a_for(self, b):
        return self._b_to_a.get(b)

    def unlink(self, a):
        if a not in self._a_to_b:
            return False
        b = self._a_to_b.pop(a)
        del self._b_to_a[b]
        return True

    def __len__(self):
        return len(self._a_to_b)

    def to_json(self):
        return json.dumps([[a, self._a_to_b[a]] for a in sorted(self._a_to_b)])

    @classmethod
    def from_json(cls, text):
        data = json.loads(text)
        if not isinstance(data, list):
            raise ValueError("expected a list of pairs")
        result = cls()
        for pair in data:
            if not isinstance(pair, list) or len(pair) != 2 or not all(isinstance(x, str) for x in pair):
                raise ValueError(f"bad pair: {pair!r}")
            result.link(pair[0], pair[1])
        return result
